package com.twu.biblioteca;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Created by Niko on 13/9/2015.
 */
public class BookTest {
    Book bookOne;
    Book bookTwo;

    @Before
    public void setUp() {
        bookOne = new Book("Test Driven Development", "Kent Beck", "2002");
        bookTwo = new Book("Head First Java", "Kathy Sierra & Bert Bates", "2005");
    }

    @Test
    public void testToString(){
        assertEquals("Test Driven Development by Kent Beck, 2002", bookOne.toString());
    }

    @Test
    public void testEquals(){
        Book sameAsBookOne = new Book("Test Driven Development", "Kent Beck", "2002");
        Book sameAsBookOneWithDiffCase = new Book("teST DriVen DevELOPment", "Kent BECK", "2002");

        assertEquals("Same book object", bookOne, bookOne);
        assertEquals("Different book objects with same values", bookOne, sameAsBookOne);
        assertEquals("Different book objects with same values in diff upperCases", bookOne, sameAsBookOneWithDiffCase);

        assertNotEquals(bookOne, bookTwo);
    }
}

{% extends 'reports/filters/base.html' %}
{% load hq_shared_tags %}
{% load i18n %}
{% block filter_content %}
{% if is_empty %}
<div class="alert alert-info">{{ empty_text }}</div>
{% else %}
<div id="{{ css_id }}" class="well well-sm">
    <div data-bind="foreach: controls">
        <div class="form-group"
             data-bind="visible: is_visible">
            <label data-bind="attr: {for: '{{ css_id }}_'+slug}, text: label"
                   class="control-label col-xs-4 col-md-2"></label>
            <div class="col-xs-8 col-md-10">
                <select  class="form-control" data-bind="attr: {id: '{{ css_id }}_'+slug, name: '{{ slug }}_'+slug},
                options: control_options, optionsText: 'text', optionsValue: 'val', optionsCaption: default_text,
                value: selected,
                event: {change: function (data, event) { $parent.updateNextDrilldown(level);  }}"></select>
            </div>
        </div>
        {% if use_last %}
        <div class="form-group" data-bind="visible: show_next_drilldown">
            <label class="control-label col-xs-4 col-md-2">
                <div class="label label-default">{% trans 'Next' %}: <strong data-bind="text: label"></strong></div>
            </label>
            <div class="col-xs-8 col-md-10">
                <select class="form-control" disabled="disabled"></select>
            </div>
        </div>
        {% endif %}
    </div>
    <div class="alert alert-info" data-bind="fadeVisible: notification.is_visible, html: notification.message"></div>
 </div>
 {% endif %}
{% endblock %}
{% block filter_js %}
{% if not is_empty %}
<script>
    $.getScript("{% static 'reports/ko/report_filter.drilldown_options.js' %}", function () {
       $('#{{ css_id }}').drilldownOptionFilter({
           drilldown_map: {{ option_map|JSON }},
           controls: {{ controls|JSON }},
           selected: {{ selected|JSON }},
           notifications: {{ notifications|JSON }},
       });
    });
</script>
{% endif %}
{% endblock %}
